import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import Sidebar from './Sidebar';
import AIChatbot from './AIChatbot';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';

const pageTitles = {
  '/dashboard': 'Dashboard',
  '/assessment': 'Mental Health Assessment',
  '/analytics': 'Analytics',
  '/recommendations': 'Recommendations',
  '/chat': 'AI Wellness Assistant',
  '/profile': 'Profile',
  '/admin': 'Admin Panel',
};

export default function Layout({ children }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const { user } = useAuth();
  const { theme, toggle } = useTheme();
  const location = useLocation();
  const title = pageTitles[location.pathname] || 'MindWatch AI';
  const showFab = location.pathname !== '/chat';

  return (
    <div className="d-flex min-vh-100">
      <div className="d-none d-lg-block" style={{ width: 260, flexShrink: 0 }}>
        <Sidebar />
      </div>

      {mobileOpen && (
        <>
          <div className="sidebar-overlay d-lg-none" onClick={() => setMobileOpen(false)} />
          <div className="sidebar-mobile d-lg-none">
            <Sidebar onNavigate={() => setMobileOpen(false)} />
          </div>
        </>
      )}

      <div className="flex-grow-1 d-flex flex-column min-vh-100">
        <header className="topbar">
          <div className="d-flex align-items-center gap-3">
            <button
              type="button"
              className="btn btn-link text-dark d-lg-none p-0"
              onClick={() => setMobileOpen(true)}
            >
              <i className="bi bi-list fs-4" />
            </button>
            <div>
              <h6 className="mb-0 fw-bold" style={{ fontFamily: 'var(--mw-font-display)' }}>{title}</h6>
              <small className="text-muted">Welcome back, {user?.name?.split(' ')[0]}</small>
            </div>
          </div>
          <div className="d-flex align-items-center gap-2">
            <button type="button" className="btn btn-sm btn-outline-secondary rounded-pill d-none d-md-inline-flex" onClick={toggle}>
              <i className={`bi ${theme === 'light' ? 'bi-moon' : 'bi-sun'}`} />
            </button>
            <span className="badge rounded-pill" style={{ background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', padding: '0.5rem 0.85rem' }}>
              <i className="bi bi-cpu me-1" /> AI Active
            </span>
          </div>
        </header>
        <main className="flex-grow-1 p-3 p-md-4 fade-in">{children}</main>
      </div>

      {showFab && <AIChatbot />}
    </div>
  );
}
